{"task":{"id":"sequence_101","spec":"Detect overlapping serial 101. Each non-reset rising edge consumes din; hit is high for the resulting cycle exactly when the last three non-reset samples are 101. Reset discards history and clears hit. Input 10101 produces two hits.
Use one SystemVerilog module with the exact interface. All state updates on rising clk. rst is synchronous, active high, and has priority. No other modules, file I/O, delays, or simulation-only behavior in the DUT.","interface":{"top":"sequence_101","ports":[{"name":"clk","direction":"input","width":1,"signed":false},{"name":"rst","direction":"input","width":1,"signed":false},{"name":"din","direction":"input","width":1,"signed":false},{"name":"hit","direction":"output","width":1,"signed":false}]},"constraints":"SystemVerilog; xczu3eg-sbva484-1-e; post-synthesis clock clk at 5 ns; simulation seed 1."},"current":{"revision_id":"01389fc3-6ae2-43b0-a5f3-18562d860f40","source_sha256":"1ac51c7ed25c07441b4f379f8d56158b235e1933d4dd6d10fdab817d904a2eda","source":"module sequence_101(
  input  wire clk,
  input  wire rst,
  input  wire din,
  output reg  hit
);
  reg [1:0] hist;

  // Last three consumed samples are {hist[1], hist[0], din}.
  // Hit when they equal 1,0,1.
  wire detect = (hist == 2'b10) & din;

  always @(posedge clk) begin
    if (rst) begin
      hist <= 2'b00;
      hit  <= 1'b0;
    end else begin
      hist <= {hist[0], din};
      hit  <= detect;
    end
  end
endmodule
